# Monitor for VSS deletion attempts
# This is often the last action before encryption

# Search Windows Event Logs for vssadmin activity
Get-WinEvent -FilterHashtable @{
    LogName = 'Microsoft-Windows-VSS*'
    Id = 8224  # VSS backup completed
} | Select-Object TimeCreated, Message | Format-Table -AutoSize

# Detect mass file rename/encryption via Sysmon Event ID 11 (FileCreate)
# Look for >50 file extensions changed per minute per host
Get-WinEvent -FilterHashtable @{
    LogName = 'Microsoft-Windows-Sysmon/Operational'
    Id = 11
} -MaxEvents 1000 | Where-Object {
    $_.Message -match '\.(locked|encrypted|crypt|ransom)'
} | Group-Object {$_.TimeCreated.Minute} | Where-Object {$_.Count -gt 50}

# Check for suspicious network tools (Rclone exfiltration)
Get-WinEvent -FilterHashtable @{
    LogName = 'Microsoft-Windows-Sysmon/Operational'
    Id = 1  # Process Create
} | Where-Object {
    $_.Message -match 'rclone|MEGAcmd|restic' -and
    $_.Message -notmatch 'C:\\Program Files\\backup'
} | Select-Object TimeCreated, Message

